 'use strict';
let analyticsDays=7,analyticsScope='current',analyticsFrom='',analyticsTo='';
const analyticsDay=t=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t));
function analyticsRange(time=Date.now()){
 const today=analyticsDay(time),midnight=d=>Date.parse(d+'T00:00:00+03:00');let start,end=time,hourly=false,label='';
 if(analyticsDays===1){start=time-86400000;hourly=true;label='آخر ٢٤ ساعة';}
 else if(analyticsDays===0&&analyticsFrom&&analyticsTo&&analyticsFrom<=analyticsTo&&Date.parse(analyticsTo)-Date.parse(analyticsFrom)<=3660*86400000){start=midnight(analyticsFrom);end=midnight(analyticsTo)+86400000-1;label=analyticsFrom+' — '+analyticsTo;}
 else if(analyticsDays===180||analyticsDays===365){const d=new Date(midnight(today));analyticsDays===180?d.setUTCMonth(d.getUTCMonth()-6):d.setUTCFullYear(d.getUTCFullYear()-1);start=d.getTime();label=analyticsDays===180?'آخر ٦ أشهر':'آخر سنة';}
 else{start=midnight(today)-(Math.max(1,analyticsDays||7)-1)*86400000;label='آخر '+fmt(analyticsDays||7)+' أيام';}
 return {start,end,hourly,label};
}
function loyaltyAnalytics(shops,days=7,time=Date.now(),range=null){
 const r=range||{start:Date.parse(analyticsDay(time-(days-1)*86400000)+'T00:00:00+03:00'),end:time,hourly:false};const unit=r.hourly?3600000:86400000,key=t=>r.hourly?String(Math.min(23,Math.floor((t-r.start)/unit))):analyticsDay(t),count=r.hourly?24:Math.round((Date.parse(analyticsDay(r.end)+'T00:00:00+03:00')-Date.parse(analyticsDay(r.start)+'T00:00:00+03:00'))/unit)+1;
 const buckets=Array.from({length:Math.max(1,count)},(_,i)=>({key:key(r.start+i*unit),time:r.start+i*unit,visits:0,rewards:0,customers:0})),map=new Map(buckets.map(b=>[b.key,b]));let members=0,available=0;const today={visits:0},yesterday={visits:0},todayKey=analyticsDay(time),yesterdayKey=analyticsDay(time-86400000);
 for(const s of shops){members+=s.members.length;available+=s.members.reduce((n,m)=>n+Loyalty.available(m,s.card),0);for(const m of s.members){if(m.joined<r.start||m.joined>r.end)continue;const b=map.get(key(m.joined||0));if(b)b.customers++;}for(const l of s.logs){if(l.undone||!['stamp','redeem'].includes(l.type))continue;if(l.type==='stamp'){if(analyticsDay(l.time)===todayKey)today.visits++;if(analyticsDay(l.time)===yesterdayKey)yesterday.visits++;}if(l.time<r.start||l.time>r.end)continue;const b=map.get(key(l.time));if(b)b[l.type==='stamp'?'visits':'rewards']++;}}
 const total=k=>buckets.reduce((n,b)=>n+b[k],0);return {buckets,members,available,today,totals:{visits:total('visits'),rewards:total('rewards'),customers:total('customers')},change:today.visits-yesterday.visits,hourly:r.hourly,range:r};
}

function analyticsBar(data,key,label,color){if(data.buckets.length>60){const groups=new Map();for(const b of data.buckets){const k=analyticsDay(b.time).slice(0,7);if(!groups.has(k))groups.set(k,{...b,visits:0,rewards:0,customers:0});const g=groups.get(k);for(const field of ['visits','rewards','customers'])g[field]+=b[field];}data={...data,buckets:[...groups.values()],monthly:true};}const max=Math.max(1,...data.buckets.map(b=>b[key])),w=680,h=210,pad=28,step=(w-pad*2)/data.buckets.length,bw=Math.min(34,step*.65);return `<div class="analytics-chart"><svg viewBox="0 0 ${w} ${h+35}" role="img" aria-label="${label}" style="--chart-color:${color}">${[0,1,2,3].map(i=>{const y=20+i*(h-35)/3;return `<line x1="${pad}" y1="${y}" x2="${w-pad}" y2="${y}" stroke="#e5ece8" stroke-dasharray="3 4"/><text x="6" y="${y+4}" fill="#82948b" font-size="10">${fmt(Math.round(max*(3-i)/3))}</text>`;}).join('')}${data.buckets.map((b,i)=>{const bh=b[key]/max*(h-35),x=pad+i*step+(step-bw)/2,y=h-15-bh,date=data.hourly?new Date(b.time).toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Riyadh'}):new Date(b.time).toLocaleDateString('ar-SA',{...(data.monthly?{year:'numeric'}:{day:'numeric'}),month:'short',timeZone:'Asia/Riyadh'});return `<g tabindex="0"><title>${date}: ${fmt(b[key])} ${label}</title><rect x="${x}" y="${y}" width="${bw}" height="${Math.max(bh,2)}" rx="5" fill="var(--chart-color)" opacity="${b[key]?1:.18}"/>${data.buckets.length<=12||i%5===0?`<text x="${x+bw/2}" y="${h+15}" text-anchor="middle" fill="#73877d" font-size="10">${date}</text>`:''}</g>`;}).join('')}</svg></div>`;}
const analyticsOwner=ownerHTML;
ownerHTML=function(){if(view!=='overview')return analyticsOwner();const all=db.shops.filter(s=>!s.archivedAt),selected=analyticsScope==='all'?all:[all.find(s=>s.id===analyticsScope)||shop()],range=analyticsRange(),a=loyaltyAnalytics(selected,analyticsDays,Date.now(),range),name=analyticsScope==='all'?'جميع برامج النشاط':selected[0].card.title||selected[0].name;const metric=(label,value,detail,i)=>`<article class="analytics-metric"><span>${label} ${icon(i)}</span><b>${fmt(value)}</b><small>${detail}</small></article>`;
 return head('أداء برامج الولاء','نظرة عامة',esc(name),`<button class="btn primary" data-action="nav" data-view="join">${icon('link')} رابط التسجيل</button>`)+`<div class="analytics-toolbar"><label>البيانات <select data-analytics="scope" aria-label="نطاق الإحصاءات">${all.map(s=>`<option value="${esc(s.id)}" ${(analyticsScope==='current'?shop().id:analyticsScope)===s.id?'selected':''}>${esc(s.card.title||s.name||'بطاقة الولاء')}</option>`).join('')}<option value="all" ${analyticsScope==='all'?'selected':''}>جميع البطاقات</option></select></label><label>الفترة <select data-analytics="days" aria-label="فترة الإحصاءات">${[[1,'اليوم · آخر ٢٤ ساعة'],[7,'آخر ٧ أيام'],[30,'آخر ٣٠ يومًا'],[180,'آخر ٦ أشهر'],[365,'آخر سنة'],[0,'تاريخ مخصص']].map(([v,t])=>`<option value="${v}" ${analyticsDays===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="analytics-calendar"><label>من <input type="date" data-analytics="from" aria-label="من تاريخ" value="${analyticsFrom}"></label><label>إلى <input type="date" data-analytics="to" aria-label="إلى تاريخ" value="${analyticsTo}"></label><button class="btn secondary small" data-action="analytics-range">عرض</button></div><small>التوقيت: الرياض · العمليات المتراجع عنها مستبعدة</small></div><div class="analytics-metrics">${metric('عملاء البرنامج',a.members,'عدد عضويات العملاء في البطاقات المختارة','users')}${metric('زيارات اليوم',a.today.visits,`${a.change>0?'زيادة':a.change<0?'انخفاض':'دون تغير'} ${fmt(Math.abs(a.change))} مقارنة بأمس`,'coffee')}${metric('مكافآت جاهزة',a.available,'متاحة للعملاء ولم تُصرف بعد','gift')}${metric('مكافآت مصروفة',a.totals.rewards,range.label,'check')}</div><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>حركة الزيارات</h2><p>الزيارات المؤهلة حسب الفترة · تشمل إضافة النقاط</p></div><b>${fmt(a.totals.visits)} زيارة</b></div>${analyticsBar(a,'visits','زيارات','#315c49')}</section><section class="panel"><div class="panel-head"><div><h2>المكافآت المصروفة</h2><p>المكافآت التي سلّمها فريقك فعليًا</p></div><b>${fmt(a.totals.rewards)} مكافأة</b></div>${analyticsBar(a,'rewards','مكافآت مصروفة','#92ad54')}</section><section class="panel"><div class="panel-head"><div><h2>العملاء الجدد</h2><p>عضويات انضمت للبرنامج خلال الفترة</p></div><b>${fmt(a.totals.customers)} عميل</b></div>${analyticsBar(a,'customers','عملاء جدد','#708f81')}</section><section class="panel"><div class="panel-head"><div><h2>آخر العمليات</h2><p>زيارات ومكافآت من البطاقات المختارة</p></div><button class="btn quiet small" data-action="nav" data-view="activity">سجل البطاقة</button></div>${logsHTML(selected.flatMap(s=>s.logs.filter(l=>!l.undone&&l.time>=range.start&&l.time<=range.end).map(l=>({...l,shopName:s.card.title||s.name}))).sort((a,b)=>b.time-a.time),5)}</section></div>`;};
document.addEventListener('click',e=>{if(e.target.closest('[data-action=analytics-range]')){const from=document.querySelector('[data-analytics=from]').value,to=document.querySelector('[data-analytics=to]').value;if(!from||!to||from>to||Date.parse(to)-Date.parse(from)>3660*86400000)return toast('اختر فترة صحيحة لا تتجاوز عشر سنوات.');analyticsFrom=from;analyticsTo=to;analyticsDays=0;render();}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-analytics]'))return;if(['from','to'].includes(e.target.dataset.analytics)){if(e.target.dataset.analytics==='from')analyticsFrom=e.target.value;else analyticsTo=e.target.value;return;}if(e.target.dataset.analytics==='days'){if(e.target.value==='0'&&(!analyticsFrom||!analyticsTo)){analyticsFrom=analyticsDay(Date.now()-6*86400000);analyticsTo=analyticsDay(Date.now());}analyticsDays=Number(e.target.value);}else analyticsScope=e.target.value;render();});
render();
